/// WebSocket消息类型
enum MessageType {
  /// 匹配请求
  matchRequest,

  /// 匹配成功
  matchFound,

  /// 匹配取消
  matchCanceled,

  /// 移动指令
  move,

  /// LAN 权威协议消息，payload 为完整 LanProtocolMessage JSON
  lanProtocol,

  /// LAN 客户端请求主机发送全量快照
  lanSnapshotRequest,

  /// LAN 客户端请求主机开始复局
  lanRestartRequest,

  /// 游戏结束
  gameOver,

  /// 断开连接
  disconnect,

  /// 重新连接
  reconnect,

  /// 心跳包
  heartbeat,

  /// 错误消息
  error,
}

extension MessageTypeExtension on MessageType {
  /// 转换为JSON字符串
  String toJson() {
    return toString().split('.').last;
  }

  /// 从JSON字符串创建
  static MessageType fromJson(String json) {
    return MessageType.values.firstWhere(
      (e) => e.toString().split('.').last == json,
      orElse: () => MessageType.error,
    );
  }

  /// 获取显示名称
  String get displayName {
    switch (this) {
      case MessageType.matchRequest:
        return '匹配请求';
      case MessageType.matchFound:
        return '匹配成功';
      case MessageType.matchCanceled:
        return '匹配取消';
      case MessageType.move:
        return '移动';
      case MessageType.lanProtocol:
        return 'LAN权威协议';
      case MessageType.lanSnapshotRequest:
        return 'LAN快照请求';
      case MessageType.lanRestartRequest:
        return 'LAN复局请求';
      case MessageType.gameOver:
        return '游戏结束';
      case MessageType.disconnect:
        return '断开连接';
      case MessageType.reconnect:
        return '重新连接';
      case MessageType.heartbeat:
        return '心跳';
      case MessageType.error:
        return '错误';
    }
  }

  /// 是否需要响应
  bool get requiresResponse {
    switch (this) {
